def slidingPuzzle(board: [[int]]) -> int
  start = tuple(board[0] + board[1])
  nbrs = {0: [1, 3], 1: [0, 2, 4], 2: [1, 5], 3: [0, 4], 4: [1, 3, 5], 5: [2, 4]}
  q, seen = deque([(start, start.index(0))]), {start}
  for (d, (s, z)) in levels(q)
    if s == (1, 2, 3, 4, 5, 0)
      return d
    for a in nbrs[z]
      ns = tuple(s[a] if i == z else s[z] if i == a else s[i] for i in range(6))
      if ns not in seen
        seen.add(ns)
        q <- (ns, a)
  -1

